<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Producto - TecnoStore</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="form-main"><a class="back" href="index.php?controller=producto&action=listar">← Volver a productos</a><div class="form-card"><h1><?=$producto?'Editar':'Agregar'?> producto</h1><form method="post" action="index.php?controller=producto&action=<?=$producto?'actualizar':'guardar'?>"><?php if($producto): ?><input type="hidden" name="id" value="<?=$producto['id']?>"><?php endif; ?><label>Nombre</label><input name="nombre" required value="<?=htmlspecialchars($producto['nombre']??'')?>"><label>Categoría</label><input name="categoria" required value="<?=htmlspecialchars($producto['categoria']??'')?>"><div class="two"><div><label>Precio (S/)</label><input type="number" step="0.01" name="precio" required value="<?=htmlspecialchars($producto['precio']??'')?>"></div><div><label>Stock</label><input type="number" name="stock" required value="<?=htmlspecialchars($producto['stock']??'')?>"></div></div><label>Icono</label><input name="imagen" value="<?=htmlspecialchars($producto['imagen']??'💻')?>"><label>Descripción</label><textarea name="descripcion"><?=htmlspecialchars($producto['descripcion']??'')?></textarea><label class="publish-option"><input type="checkbox" name="publicado" value="1" <?=((int)($producto['publicado']??0)===1?'checked':'')?>> Publicar en el catálogo del cliente</label><p class="help">Si lo dejas desmarcado, el producto quedará guardado solo en administración y no aparecerá en el catálogo.</p><button class="btn">Guardar producto</button></form></div></main></body></html>
